"""App icon for the Torbox Downloader window/taskbar (round R9).

An ORIGINAL design (redrawn in R11 after the user rejected the first),
drawn with Pillow (tools/make-icon-r11.py) and shipped as a base64-encoded
256x256 PNG: a bold white download arrow dropping into a tray, on a rounded
square with a diagonal electric-indigo-to-violet gradient. Flat, no text,
no existing product's logo or mascot.

ICON_PNG_B64 is the whole PNG file, base64-encoded. make_photo_image()
decodes it into a tk.PhotoImage (Tk 8.6 renders PNG natively); the caller
must keep a reference to the returned image or Tk garbage-collects it and
the icon disappears. The icon is purely cosmetic: every failure here
returns None so a broken/old Tk build never blocks app startup.

No secrets are ever printed or logged by this module.
"""

from __future__ import annotations

import base64
import tkinter as tk

ICON_PNG_B64 = ""


def make_photo_image(tk_root) -> "tk.PhotoImage | None":
    """Decode ICON_PNG_B64 into a tk.PhotoImage for tk_root.

    Returns None when the interpreter's Tk build cannot render PNG or the
    decode fails for any reason — the icon is decoration, never a hard
    dependency. The caller must keep the returned reference alive
    (e.g. self._icon_img) for as long as the window lives."""
    try:
        raw = base64.b64decode(ICON_PNG_B64)
        return tk.PhotoImage(master=tk_root, data=raw)
    except Exception:
        return None
